"""Re-plan policy: greedy best-insertion, then a local-search pass that
relocates / swaps / drops jobs and inserts unassigned work, keeping a move
only when the full estimated cost (travel + lateness + overtime + emergency
wait + unscheduled penalties + churn penalties) strictly drops.
"""

from dispatchiq.helpers import drop_until_feasible, route_cost


def replan(state):
    techs = state["techs"]
    jobs = state["jobs"]
    tid2tech = {t["id"]: t for t in techs}
    healthy_ids = [t["id"] for t in techs if not t["sick"]]
    healthy_set = set(healthy_ids)

    # ---------- initial plan: healthy techs keep their morning work ----------
    plan = {t["id"]: [] for t in techs}
    seen = set()
    for t in techs:
        if t["sick"]:
            continue
        for jid in t["remaining"]:
            if jid not in seen and jid in jobs:
                seen.add(jid)
                plan[t["id"]].append(jid)

    orphans = []
    for t in techs:
        if not t["sick"]:
            continue
        for jid in t["remaining"]:
            if jid not in seen and jid in jobs:
                seen.add(jid)
                orphans.append(jid)

    emergencies = [jid for jid, j in jobs.items()
                   if j.get("emergency") and jid not in seen]

    unassigned = set()
    memo = {}
    budget = [30000]

    def rc(tid, seq):
        if not seq:
            return 0.0
        key = (tid, tuple(seq))
        v = memo.get(key)
        if v is None:
            v = route_cost(state, tid2tech[tid], seq)
            memo[key] = v
            budget[0] -= 1
        return v

    def move_pen(jid, tid):
        mt = jobs[jid].get("morning_tech")
        if mt is None or mt == tid or mt not in healthy_set:
            return 0
        return 20

    # ---------- repair any infeasible morning sequence ----------
    for tid in healthy_ids:
        seq = plan[tid]
        if seq and rc(tid, seq) >= 1e6:
            kept, dropped = drop_until_feasible(state, tid2tech[tid], seq)
            if not any(jobs[d].get("emergency") for d in dropped):
                plan[tid] = kept
                for d in dropped:
                    unassigned.add(d)

    # ---------- greedy best insertion ----------
    def insert_job(jid):
        job = jobs[jid]
        skill = job["skill"]
        is_em = bool(job.get("emergency"))
        best = None  # (delta, tech, new_seq, dropped)
        for B in healthy_ids:
            if skill not in tid2tech[B]["skills"]:
                continue
            seqB = plan[B]
            base = rc(B, seqB)
            mp = move_pen(jid, B)
            for pos in range(len(seqB) + 1):
                nseq = seqB[:pos] + [jid] + seqB[pos:]
                c = rc(B, nseq)
                if c < 1e6:
                    delta = c - base + mp
                    if best is None or delta < best[0]:
                        best = (delta, B, nseq, [])
                elif is_em:
                    kept, dropped = drop_until_feasible(state, tid2tech[B], nseq)
                    if jid not in kept:
                        continue
                    if any(jobs[d].get("emergency") for d in dropped):
                        continue
                    ck = rc(B, kept)
                    if ck >= 1e6:
                        continue
                    delta = ck - base + mp
                    for d in dropped:
                        delta += 150 * jobs[d]["priority"] - move_pen(d, B)
                    if best is None or delta < best[0]:
                        best = (delta, B, kept, dropped)
        if best is None:
            return False
        _, B, nseq, dropped = best
        plan[B] = nseq
        for d in dropped:
            unassigned.add(d)
        return True

    for jid in sorted(emergencies,
                      key=lambda j: (jobs[j].get("release", 0),
                                     -jobs[j]["priority"])):
        if not insert_job(jid):
            unassigned.add(jid)

    for jid in sorted(orphans,
                      key=lambda j: (-jobs[j]["priority"],
                                     jobs[j].get("latest", 10 ** 9))):
        if not insert_job(jid):
            unassigned.add(jid)

    # ---------- local search ----------
    MAX_PASSES = 12
    EPS = 1e-7
    n_tech = len(healthy_ids)

    for _pass in range(MAX_PASSES):
        if budget[0] <= 0:
            break
        best_delta = -EPS
        best_move = None
        # tuple layout: (kind, A, seqA, B, seqB, jid, dropped)

        # (0) insert unassigned jobs
        for jid in list(unassigned):
            job = jobs[jid]
            skill = job["skill"]
            pen = 150 * job["priority"]
            for B in healthy_ids:
                if skill not in tid2tech[B]["skills"]:
                    continue
                seqB = plan[B]
                base = rc(B, seqB)
                mp = move_pen(jid, B)
                for pos in range(len(seqB) + 1):
                    nseq = seqB[:pos] + [jid] + seqB[pos:]
                    c = rc(B, nseq)
                    if c < 1e6:
                        delta = c - base - pen + mp
                        if delta < best_delta:
                            best_delta = delta
                            best_move = (0, B, nseq, None, None, jid, [])
                    else:
                        kept, dropped = drop_until_feasible(
                            state, tid2tech[B], nseq)
                        if jid not in kept:
                            continue
                        if any(jobs[d].get("emergency") for d in dropped):
                            continue
                        ck = rc(B, kept)
                        if ck >= 1e6:
                            continue
                        delta = ck - base - pen + mp
                        for d in dropped:
                            delta += 150 * jobs[d]["priority"] - move_pen(d, B)
                        if delta < best_delta:
                            best_delta = delta
                            best_move = (0, B, kept, None, None, jid, dropped)

        # (1) drop assigned non-emergency jobs
        for A in healthy_ids:
            seqA = plan[A]
            if not seqA:
                continue
            baseA = rc(A, seqA)
            for i, jid in enumerate(seqA):
                if jobs[jid].get("emergency"):
                    continue
                nseq = seqA[:i] + seqA[i + 1:]
                c = rc(A, nseq)
                if c >= 1e6:
                    continue
                delta = c - baseA + 150 * jobs[jid]["priority"] - move_pen(jid, A)
                if delta < best_delta:
                    best_delta = delta
                    best_move = (1, A, nseq, None, None, jid, None)

        # (2) intra-tech reorder
        for A in healthy_ids:
            seqA = plan[A]
            n = len(seqA)
            if n < 2:
                continue
            baseA = rc(A, seqA)
            for i in range(n):
                jid = seqA[i]
                red = seqA[:i] + seqA[i + 1:]
                for pos in range(n):
                    if pos == i:
                        continue
                    nseq = red[:pos] + [jid] + red[pos:]
                    c = rc(A, nseq)
                    if c >= 1e6:
                        continue
                    delta = c - baseA
                    if delta < best_delta:
                        best_delta = delta
                        best_move = (2, A, nseq, None, None, None, None)

        # (3) cross-tech relocate
        for A in healthy_ids:
            seqA = plan[A]
            if not seqA:
                continue
            baseA = rc(A, seqA)
            for i, jid in enumerate(seqA):
                skill = jobs[jid]["skill"]
                red = seqA[:i] + seqA[i + 1:]
                c_red = rc(A, red)
                if c_red >= 1e6:
                    continue
                old_pen = move_pen(jid, A)
                for B in healthy_ids:
                    if B == A:
                        continue
                    if skill not in tid2tech[B]["skills"]:
                        continue
                    seqB = plan[B]
                    baseB = rc(B, seqB)
                    pen_delta = move_pen(jid, B) - old_pen
                    for pos in range(len(seqB) + 1):
                        nseqB = seqB[:pos] + [jid] + seqB[pos:]
                        c = rc(B, nseqB)
                        if c >= 1e6:
                            continue
                        delta = (c_red + c) - (baseA + baseB) + pen_delta
                        if delta < best_delta:
                            best_delta = delta
                            best_move = (3, A, red, B, nseqB, jid, None)

        # (4) intra-tech swap
        for A in healthy_ids:
            seqA = plan[A]
            n = len(seqA)
            if n < 2:
                continue
            baseA = rc(A, seqA)
            for i in range(n):
                for j in range(i + 1, n):
                    nseq = list(seqA)
                    nseq[i], nseq[j] = nseq[j], nseq[i]
                    c = rc(A, nseq)
                    if c >= 1e6:
                        continue
                    delta = c - baseA
                    if delta < best_delta:
                        best_delta = delta
                        best_move = (2, A, nseq, None, None, None, None)

        # (5) cross-tech swap
        for ai in range(n_tech):
            A = healthy_ids[ai]
            seqA = plan[A]
            if not seqA:
                continue
            baseA = rc(A, seqA)
            skillsA = tid2tech[A]["skills"]
            for bi in range(ai + 1, n_tech):
                B = healthy_ids[bi]
                seqB = plan[B]
                if not seqB:
                    continue
                skillsB = tid2tech[B]["skills"]
                baseB = rc(B, seqB)
                for i, ja in enumerate(seqA):
                    if jobs[ja]["skill"] not in skillsB:
                        continue
                    for j, jb in enumerate(seqB):
                        if jobs[jb]["skill"] not in skillsA:
                            continue
                        nseqA = seqA[:i] + [jb] + seqA[i + 1:]
                        nseqB = seqB[:j] + [ja] + seqB[j + 1:]
                        ca = rc(A, nseqA)
                        cb = rc(B, nseqB)
                        if ca >= 1e6 or cb >= 1e6:
                            continue
                        delta = (ca + cb) - (baseA + baseB)
                        delta += move_pen(ja, B) - move_pen(ja, A)
                        delta += move_pen(jb, A) - move_pen(jb, B)
                        if delta < best_delta:
                            best_delta = delta
                            best_move = (4, A, nseqA, B, nseqB, None, None)

        if best_move is None:
            break

        kind = best_move[0]
        if kind == 0:
            _, B, nseq, _, _, jid, dropped = best_move
            plan[B] = nseq
            unassigned.discard(jid)
            for d in (dropped or []):
                unassigned.add(d)
        elif kind == 1:
            _, A, nseq, _, _, jid, _ = best_move
            plan[A] = nseq
            unassigned.add(jid)
        elif kind == 2:
            _, A, nseq, _, _, _, _ = best_move
            plan[A] = nseq
        elif kind == 3:
            _, A, red, B, nseqB, _, _ = best_move
            plan[A] = red
            plan[B] = nseqB
        else:  # kind == 4
            _, A, nseqA, B, nseqB, _, _ = best_move
            plan[A] = nseqA
            plan[B] = nseqB

    return {tid: list(seq) for tid, seq in plan.items()}
